contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: amount is the Ether forwarded to c.go
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // observe owner before
        address ownerBefore = c.owner();
        // observe balance of c before
        uint256 balBefore = address(c).balance;

        // perform the call, capturing whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe owner and balance after
        address ownerAfter = c.owner();
        uint256 balAfter = address(c).balance;

        // General rule: if the call succeeded, owner must be unchanged and contract balance must be zero
        // If the call reverted, we impose no further constraints. Also ensure owner is unchanged even on revert.
        assert(ownerAfter == ownerBefore && (reverted || balAfter == 0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read owner and balance before
        address beforeOwner = c.owner();
        uint beforeBal = address(c).balance;
        bool reverted;
        // perform the call sending `amount` wei to c.go
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // after-values
        address afterOwner = c.owner();
        uint afterBal = address(c).balance;
        // General rule: either the call reverted, or owner unchanged and c's balance is zero
        assert(reverted || (afterOwner == beforeOwner && afterBal == 0));
    }
    receive() external payable {}
}

